<script setup>
import { ChevronDown } from 'lucide-vue-next'; import { computed } from 'vue'; const props = defineProps({ modelValue: [String, Number], label: String, options: { type: Array, default: () => [] }, placeholder: String, error: String, helper: String, required: Boolean, disabled: Boolean, id: String }); const emit = defineEmits(['update:modelValue']); const selectId = computed(() => props.id || `select-${Math.random().toString(36).slice(2)}`);
</script>
<template><div><label v-if="label" :for="selectId" class="mb-1.5 block text-sm font-medium text-[#172033]">{{ label }} <span v-if="required" class="text-red-500">*</span></label><div class="relative"><select :id="selectId" :value="modelValue" :disabled="disabled" :class="['ui-field appearance-none px-3 pr-9', error && 'ui-field--error']" @change="emit('update:modelValue', $event.target.value)"><option v-if="placeholder" value="" disabled>{{ placeholder }}</option><option v-for="option in options" :key="typeof option === 'object' ? option.value : option" :value="typeof option === 'object' ? option.value : option">{{ typeof option === 'object' ? option.label : option }}</option></select><ChevronDown :size="14" class="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[#9CA3AF]" /></div><p v-if="error" class="mt-1 text-xs text-[#DC2626]">{{ error }}</p><p v-else-if="helper" class="mt-1 text-xs text-[#667085]">{{ helper }}</p></div></template>
